import SwiftUI
struct DashboardView:View{@State private var status="Not checked";var body:some View{NavigationStack{ScrollView{VStack(alignment:.leading,spacing:16){Text("COMMAND DECK").font(.caption.bold()).tracking(2).foregroundStyle(.cyan);Text("Universal IDE").font(.largeTitle.bold());Text("Edit projects, manage repositories, and dispatch builds from one workspace.").foregroundStyle(.secondary);GroupBox("Server connection"){HStack{Circle().fill(status=="Connected" ? .green:.orange).frame(width:8,height:8);Text(status);Spacer();Button("Check"){Task{do{let _:APIHealth=try await APIClient.shared.get("/api/v1/health",as:APIHealth.self);status="Connected"}catch{status="Unavailable"}}}}};GroupBox("Capabilities"){VStack(alignment:.leading){Label("Swift / SwiftUI editing",systemImage:"swift");Label("C# and Lua need runtime adapters",systemImage:"curlybraces");Label("GitHub sync adapter required",systemImage:"arrow.triangle.branch");Label("Isolated build workers required",systemImage:"server.rack")}.frame(maxWidth:.infinity,alignment:.leading)}}.padding()}.navigationTitle("Workspace")}}}
